import { mkdir, rename, stat } from 'node:fs/promises';
import path from 'node:path';
import type { Pool } from 'pg';

/** Names generated by the API: 32 hex characters and `.webp`. */
const IMAGE_FILE = /^[a-f0-9]{32}\.webp$/;

/** Folder of a household's pictures, inside IMAGES_DIR. */
export function householdImageDir(imagesDir: string, householdId: number): string {
  return path.join(path.resolve(imagesDir), `h${householdId}`);
}

async function exists(file: string): Promise<boolean> {
  return stat(file).then(
    () => true,
    () => false,
  );
}

/**
 * Before households, every thumbnail sat at the root of IMAGES_DIR. Moves each one used by a
 * product into the folder of that product's household. Best effort and idempotent: a file already
 * moved, missing or shared is left alone (the image route still reads the old place). Runs with the
 * owner connection, which sees the products of every household; returns the number of files moved.
 */
export async function relocateLegacyImages(owner: Pool, imagesDir: string): Promise<number> {
  const { rows } = await owner.query<{ household_id: number; image_path: string }>(
    'SELECT DISTINCT household_id, image_path FROM products WHERE image_path IS NOT NULL',
  );
  let moved = 0;
  for (const row of rows) {
    if (!IMAGE_FILE.test(row.image_path)) continue;
    const from = path.join(path.resolve(imagesDir), row.image_path);
    const dir = householdImageDir(imagesDir, row.household_id);
    const to = path.join(dir, row.image_path);
    if (!(await exists(from)) || (await exists(to))) continue;
    try {
      await mkdir(dir, { recursive: true });
      await rename(from, to);
      moved += 1;
    } catch {
      // Left where it is: the image route falls back to the old place.
    }
  }
  return moved;
}
